// Post one short message per lifecycle event. The webhook URL is a Secret:
// it is never part of the message, the output or an error.
const ui = 'http://127.0.0.1:4310';
const outcome = {
  completed: 'completed',
  failed: 'failed',
  cancelled: 'was cancelled',
  needs_attention: 'needs attention',
  stalled: 'stalled',
};
// Event text can come from issue titles or errors; escape Slack markup.
const text = (value) =>
  String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const task = input.externalTask
  ? ` (${text(input.externalTask.title ?? input.externalTask.id)})`
  : '';
const lines = [`Interlock run ${input.runId}${task} ${outcome[input.type] ?? text(input.type)}.`];
if (input.failingNode) lines.push(`Step: ${text(input.failingNode.label)}`);
if (input.error) lines.push(`Error: ${text(input.error.slice(0, 300))}`);
if (input.type === 'needs_attention' && input.waiting)
  lines.push(`Waiting for: ${text(input.waiting.kind)}`);
lines.push(`${ui}/runs/${input.runId}`);
const message = { text: lines.join('\n') };
let response;
try {
  response = await fetch(process.env.NOTIFY_WEBHOOK_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(message),
    redirect: 'error',
    signal: AbortSignal.timeout(10000),
  });
} catch (error) {
  throw new Error(`Could not reach the webhook (${error.cause?.code ?? error.name})`);
}
if (!response.ok) throw new Error(`The webhook answered HTTP ${response.status}`);
return { status: response.status, message };
